<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\Address;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class AddressStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\AddressModel',
  1 => 'App\\Controllers\\AddressController',
  2 => 'App\\Validation\\AddressRules',
  3 => 'App\\Entities\\AddressEntity',
  4 => 'App\\Services\\AddressService',
  5 => 'App\\Controllers\\Api\\V1\\AddressApiController',
  6 => 'App\\API\\Resources\\AddressResource',
  7 => 'App\\Validation\\AddressApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
